def second_largest(nums):
    """Return the second largest distinct value in nums, or None if it doesn't exist."""
    if not nums:
        return None

    first = second = None
    for n in nums:
        if first is None or n > first:
            if first is not None and n != first:
                second = first
            first = n
        elif n != first:
            if second is None or n > second:
                second = n
    return second

# Example tests
assert second_largest([3, 1, 2]) == 2
assert second_largest([5, 5]) is None
```
