def rle(s: str) -> str:
    """Run-length encode a string."""
    if not s:
        return ''
    result = []
    count = 1
    prev = s[0]
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = c
            count = 1
    result.append(f"{prev}{count}")
    return ''.join(result)
```
