def two_sum(nums, target):
    """
    Return the tuple (i, j) with i < j such that nums[i] + nums[j] == target.
    If multiple pairs exist, return the one with the smallest i, then smallest j.
    Return None if no such pair exists.
    """
    index_of = {}
    for j, val in enumerate(nums):
        complement = target - val
        if complement in index_of:
            i = index_of[complement]
            return (i, j)
        # Store the index only if not already present to keep the smallest i
        if val not in index_of:
            index_of[val] = j
    return None
