def binary_search(arr, x):
    left, right = 0, len(arr) - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            result = mid
            right = mid - 1  # continue searching left side
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return result
